package hu.boltseged.admin;
import com.fasterxml.jackson.databind.*; import hu.boltseged.label.*; import hu.boltseged.shipment.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.io.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/shipments") public class AdminShipmentController {final ShipmentRepository repo;final ShipmentLabelRepository labels;final LabelStorage storage;final ObjectMapper json;AdminShipmentController(ShipmentRepository r,ShipmentLabelRepository l,LabelStorage s,ObjectMapper j){repo=r;labels=l;storage=s;json=j;}@GetMapping("/{id}") Detail get(@PathVariable UUID id){Shipment s=repo.findDetailedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return new Detail(s.getId(),s.getAccount().getCompanyName(),s.getDhlProductCode(),s.getMasterTrackingNumber(),s.getStatus(),s.getBillingStatus(),s.getCreatedAt(),s.getDhlEstimatedCost(),s.getCustomerPrice(),s.getDhlEstimatedCost()==null||s.getCustomerPrice()==null?null:s.getCustomerPrice().subtract(s.getDhlEstimatedCost()),s.getPackages().stream().map(p->new ShipmentController.PackageView(p.getPackageIndex(),p.getTrackingNumber(),p.getWeight(),p.getLength(),p.getWidth(),p.getHeight())).toList(),tree(s.getSender()),tree(s.getRecipient()),labels.findByShipmentId(id).stream().map(x->new ShipmentController.LabelView(x.getId(),x.getFileName())).toList());}private JsonNode tree(String s){try{return json.readTree(s);}catch(Exception e){return json.createObjectNode();}}record Detail(UUID id,String company,String productCode,String masterTrackingNumber,String status,String billingStatus,Instant createdAt,BigDecimal dhlEstimatedCost,BigDecimal customerPrice,BigDecimal margin,List<ShipmentController.PackageView> packages,JsonNode sender,JsonNode recipient,List<ShipmentController.LabelView> labels){}}
